def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        nodes = list(ast.walk(tree))
        n = len(nodes)
        if n < 4:
            return 0.1
        cf = sum(1 for x in nodes if isinstance(x, (ast.If, ast.For, ast.While)))
        return min(1.0, cf * 2.0 / n)
    except:
        return 0.0

import re, hashlib

def score(program: str) -> float:
    try:
        words = set(re.findall(r"[A-Za-z_]{4,}", program))
        vals = sorted(int(hashlib.md5(w.encode()).hexdigest(), 16) % 997 / 997 for w in words)
        if not vals:
            return 0.5
        return vals[len(vals) // 2]
    except Exception:
        return 0.5

